UPDATE ui.dashboardquery SET
vcdashboardquery =  E' {
    "All":
    {
        "All" : {
            "All" : "SELECT l.dttrxntime AT TIME ZONE ''Asia/Kolkata'' AS \\"Timestamp\\", result ->> ''msg'' AS \\"Response Code\\", observations ->> ''org'' AS \\"Org\\", observations ->> ''reqid'' AS \\"Request ID\\", result ->> ''status'' AS \\"Status\\", observations -> ''txn'' ->> ''id'' AS \\"Txn ID\\", CAST( observations ->> ''ts'' AS TIMESTAMP WITH TIME ZONE ) AT TIME ZONE ''Asia/Kolkata'' AS \\"Txn Timestamp\\", observations -> ''txn'' ->> ''note'' AS \\"Note\\", observations -> ''txn'' ->> ''type'' AS \\"Type\\", CAST(CAST( CASE WHEN observations -> ''payee'' ->> ''mcc'' IN ('''', ''null'') THEN NULL ELSE observations -> ''payee'' ->> ''mcc'' END AS NUMERIC ) AS INT) AS \\"MCC\\", observations -> ''txn'' ->> ''class'' AS \\"Class\\", observations -> ''payee'' ->> ''addr'' AS \\"Payee\\", observations -> ''payee'' -> ''attribs'' -> ''identity'' ->> ''verified_name'' AS \\"Payee Name\\", observations -> ''payer'' ->> ''addr'' AS \\"Payer\\", observations -> ''payerVPA'' ->> ''vpaName'' AS \\"Payer Name\\", result -> ''score'' ->> ''score'' AS \\"Txn Score\\", ROUND( CAST( CASE WHEN observations -> ''payer'' ->> ''amount'' IN ('''', ''null'') THEN NULL ELSE observations -> ''payer'' ->> ''amount'' END AS NUMERIC ) / 100, 2 ) AS \\"Txn Amount\\", observations -> ''txn'' ->> ''orgTxnId'' AS \\"Original Txn ID\\", observations -> ''payer'' ->> ''currency'' AS \\"Currency\\", result -> ''score'' ->> ''workflow'' AS \\"Workflow Name\\", result -> ''score'' ->> ''decisiondetails'' AS \\"Decision Detail\\", observations -> ''txn'' -> ''attribs'' ->> ''terminal_type'' AS \\"Terminal Type\\", observations -> ''txn'' -> ''attribs'' ->> ''pos_entry_mode'' AS \\"POS Entry Mode\\", observations -> ''txn'' -> ''attribs'' ->> ''moto_eci_recurring'' AS \\"MOTO ECI\\", observations -> ''txn'' -> ''attribs'' ->> ''card_country_code'' AS \\"Country Code\\", observations -> ''txn'' -> ''attribs'' ->> ''pos_condition_code'' AS \\"POS Condition Code\\", observations -> ''txn'' -> ''attribs'' -> ''pismo_raw'' -> ''fields'' ->> ''cvv_data'' AS \\"CVV\\", CAST(CAST( CASE WHEN observations -> ''observations'' ->> ''payee_d01_txn_count'' IN ('''', ''null'') THEN NULL ELSE observations -> ''observations'' ->> ''payee_d01_txn_count'' END AS NUMERIC ) AS INT) AS \\"Payee D1 Txn Count\\", CAST( CASE WHEN observations -> ''observations'' ->> ''payee_d01_txn_value'' IN ('''', ''null'') THEN NULL ELSE observations -> ''observations'' ->> ''payee_d01_txn_value'' END AS FLOAT ) AS \\"Payee D1 Txn Value\\", CAST( CASE WHEN observations -> ''observations'' ->> ''payee_m60_txn_value'' IN ('''', ''null'') THEN NULL ELSE observations -> ''observations'' ->> ''payee_m60_txn_value'' END AS FLOAT ) AS \\"Payee M60 Txn Value\\", CAST(CAST( CASE WHEN observations -> ''observations'' ->> ''payee_m60_txn_count'' IN ('''', ''null'') THEN NULL ELSE observations -> ''observations'' ->> ''payee_m60_txn_count'' END AS NUMERIC ) AS INT) AS \\"Payee M60 Txn Count\\", CAST(CAST( CASE WHEN observations -> ''observations'' ->> ''payer_d01_txn_count'' IN ('''', ''null'') THEN NULL ELSE observations -> ''observations'' ->> ''payer_d01_txn_count'' END AS NUMERIC ) AS INT) AS \\"Payer D1 Txn Count\\", CAST( CASE WHEN observations -> ''observations'' ->> ''payer_d01_txn_value'' IN ('''', ''null'') THEN NULL ELSE observations -> ''observations'' ->> ''payer_d01_txn_value'' END AS FLOAT ) AS \\"Payer D1 Txn Value\\", CAST( CASE WHEN observations -> ''observations'' ->> ''payer_m60_txn_value'' IN ('''', ''null'') THEN NULL ELSE observations -> ''observations'' ->> ''payer_m60_txn_value'' END AS FLOAT ) AS \\"Payer M60 Txn Value\\", CAST(CAST( CASE WHEN observations -> ''observations'' ->> ''payer_m60_txn_count'' IN ('''', ''null'') THEN NULL ELSE observations -> ''observations'' ->> ''payer_m60_txn_count'' END AS NUMERIC ) AS INT) AS \\"Payer M60 Txn Count\\", observations -> ''txn'' -> ''attribs'' -> ''pismo_raw'' -> ''fields'' ->> ''bin'' AS \\"BIN\\", observations -> ''txn'' -> ''attribs'' -> ''pimso_raw'' -> ''fields'' ->> ''mti'' AS \\"MTI\\", observations -> ''txn'' -> ''attribs'' -> ''pimso_raw'' -> ''fields'' ->> ''tvr'' AS \\"TVR\\", CAST(CAST( CASE WHEN observations -> ''txn'' -> ''attribs'' -> ''pismo_raw'' -> ''fields'' ->> ''network_score'' IN ('''', ''null'') THEN NULL ELSE observations -> ''txn'' -> ''attribs'' -> ''pismo_raw'' -> ''fields'' ->> ''network_score'' END AS NUMERIC ) AS INT) AS \\"Network Score\\", observations -> ''txn'' -> ''attribs'' -> ''raw'' -> ''fields'' ->> ''response_code'' AS \\"Network Response Code\\", CAST( observations -> ''observations'' -> ''payerVPA'' ->> ''onboarding_date'' AS DATE ) AS \\"Payer Onboarding Dt\\",cast( case when observations ->> ''payee_as_payer_d01_txn_count'' in ('''', ''null'') then null else observations ->> ''payee_as_payer_d01_txn_count'' end as float ) as \\"payee_as_payer_d01_txn_count\\", cast( case when observations ->> ''payee_as_payer_d01_txn_value'' in ('''', ''null'') then null else observations ->> ''payee_as_payer_d01_txn_value'' end as float ) as \\"payee_as_payer_d01_txn_value\\", cast( case when observations ->> ''payee_as_payer_m60_txn_count'' in ('''', ''null'') then null else observations ->> ''payee_as_payer_m60_txn_count'' end as float ) as \\"payee_as_payer_m60_txn_count\\", cast( case when observations ->> ''payee_as_payer_m60_txn_value'' in ('''', ''null'') then null else observations ->> ''payee_as_payer_m60_txn_value'' end as float ) as \\"payee_as_payer_m60_txn_value\\", cast( case when observations ->> ''payer_as_payee_d01_txn_count'' in ('''', ''null'') then null else observations ->> ''payer_as_payee_d01_txn_count'' end as float ) as \\"payer_as_payee_d01_txn_count\\", cast( case when observations -> ''observations'' ->> ''payer_as_payee_m60_txn_count'' in ('''', ''null'') then null else observations -> ''observations'' ->> ''payer_as_payee_m60_txn_count'' end as float ) as \\"payer_as_payee_m60_txn_count\\", cast( case when observations -> ''observat